package com.sunshine.yunji.content.operation.application;
import com.sunshine.yunji.content.shared.*;
import com.sunshine.yunji.content.identity.application.Actors;
import com.sunshine.yunji.content.article.application.ArticleAccess;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.Instant;
import java.sql.Timestamp;
import java.util.*;
@Service
public class OperationService {
 private final Db db;private final Actors actors;private final ArticleAccess articles;
 public OperationService(Db db,Actors actors,ArticleAccess articles){this.db=db;this.actors=actors;this.articles=articles;}
 public record Banner(String title,String imageUrl,String linkType,String linkValue,int sortOrder,String status,Instant effectiveFrom,Instant effectiveTo){}
 public record Recommend(long articleId,String coverUrl,int sortOrder,String status,Instant effectiveFrom,Instant effectiveTo){}
 public record Page(String pageKey,String title,String content){}
 public record Column(String name,long categoryId,int sortOrder,String status){}
 private void manage(){actors.staff().require("yunji:operation:manage");}
 private Timestamp ts(Instant t){return t==null?null:Timestamp.from(t);}
 private void period(Instant from,Instant to){BusinessException.require(from==null||to==null||to.isAfter(from),422,"有效期顺序错误");}
 private void image(String value){BusinessException.require(value!=null&&value.matches("https?://[^\\s]+"),422,"图片需要HTTP(S)地址");}
 private String visible=" status='PUBLISHED' AND (effective_from IS NULL OR effective_from<=UTC_TIMESTAMP()) AND (effective_to IS NULL OR effective_to>UTC_TIMESTAMP()) ";
 public Map<String,Object> home(){return Map.of("banners",db.rows("SELECT id,title,image_url,link_type,link_value FROM banner WHERE tenant_id='000000' AND deleted_at IS NULL AND "+visible+" AND (link_type<>'ARTICLE' OR EXISTS(SELECT 1 FROM article a WHERE a.id=banner.link_value AND "+ArticleAccess.VISIBLE+")) AND (link_type<>'TOPIC' OR EXISTS(SELECT 1 FROM activity_topic t WHERE t.id=banner.link_value AND t.tenant_id='000000' AND t.status='PUBLISHED' AND t.deleted_at IS NULL)) ORDER BY sort_order,id LIMIT 20"),"recommendations",db.rows("SELECT r.id,r.article_id,r.cover_url,a.title,a.summary,a.content_type,a.source_name,a.published_at FROM home_recommendation r JOIN article a ON a.id=r.article_id WHERE r.status='PUBLISHED' AND (r.effective_from IS NULL OR r.effective_from<=UTC_TIMESTAMP()) AND (r.effective_to IS NULL OR r.effective_to>UTC_TIMESTAMP()) AND "+ArticleAccess.VISIBLE+" ORDER BY r.sort_order,r.id LIMIT 30"),"activityColumns",db.rows("SELECT col.* FROM activity_column col JOIN content_category c ON c.id=col.category_id WHERE col.tenant_id='000000' AND col.status='ENABLED' AND c.deleted_at IS NULL AND c.status='ENABLED' ORDER BY col.sort_order,col.id LIMIT 20"));}
 public List<Map<String,Object>> banners(){manage();return db.rows("SELECT * FROM banner WHERE tenant_id='000000' AND deleted_at IS NULL ORDER BY sort_order,id LIMIT 100");}
 @Transactional public Map<String,Object> banner(Long id,Banner b){manage();Db.text(b.title,150);image(b.imageUrl);period(b.effectiveFrom,b.effectiveTo);BusinessException.require(Set.of("DRAFT","PUBLISHED","OFFLINE").contains(b.status)&&Set.of("ARTICLE","PAGE","TOPIC").contains(b.linkType),422,"Banner状态或目标类型错误");if(b.linkType.equals("ARTICLE"))articles.visible(Db.number(b.linkValue));else if(b.linkType.equals("TOPIC"))db.one("SELECT id FROM activity_topic WHERE id=? AND tenant_id='000000' AND status='PUBLISHED' AND deleted_at IS NULL",Db.number(b.linkValue));else page(b.linkValue);
  long key=id==null?db.id():id;if(id==null)db.update("INSERT INTO banner(id,title,image_url,link_type,link_value,sort_order,status,effective_from,effective_to,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)",key,b.title,b.imageUrl,b.linkType,b.linkValue,b.sortOrder,b.status,ts(b.effectiveFrom),ts(b.effectiveTo),actors.staff().id());else{db.one("SELECT id FROM banner WHERE id=? AND tenant_id='000000' AND deleted_at IS NULL FOR UPDATE",id);db.update("UPDATE banner SET title=?,image_url=?,link_type=?,link_value=?,sort_order=?,status=?,effective_from=?,effective_to=? WHERE id=?",b.title,b.imageUrl,b.linkType,b.linkValue,b.sortOrder,b.status,ts(b.effectiveFrom),ts(b.effectiveTo),key);}db.audit(actors.staff().id(),"STAFF","BANNER_SAVE","BANNER",key,Map.of("title",b.title));return db.one("SELECT * FROM banner WHERE id=?",key);}
 @Transactional public void deleteBanner(long id){manage();db.one("SELECT id FROM banner WHERE id=? AND tenant_id='000000' FOR UPDATE",id);db.update("UPDATE banner SET deleted_at=UTC_TIMESTAMP(),status='OFFLINE' WHERE id=?",id);db.audit(actors.staff().id(),"STAFF","BANNER_DELETE","BANNER",id,Map.of());}
 public List<Map<String,Object>> recommendations(){manage();return db.rows("SELECT * FROM home_recommendation ORDER BY sort_order,id LIMIT 100");}
 @Transactional public Map<String,Object> recommend(Recommend b){manage();articles.visible(b.articleId);period(b.effectiveFrom,b.effectiveTo);BusinessException.require(Set.of("DRAFT","PUBLISHED","OFFLINE").contains(b.status),422,"推荐状态错误");long id=db.id();db.update("INSERT INTO home_recommendation(id,article_id,cover_url,sort_order,status,effective_from,effective_to,created_by) VALUES(?,?,?,?,?,?,?,?)",id,b.articleId,b.coverUrl,b.sortOrder,b.status,ts(b.effectiveFrom),ts(b.effectiveTo),actors.staff().id());db.audit(actors.staff().id(),"STAFF","RECOMMEND_CREATE","RECOMMENDATION",id,Map.of("articleId",Long.toString(b.articleId)));return db.one("SELECT * FROM home_recommendation WHERE id=?",id);}
 public void deleteRecommendation(long id){manage();db.one("SELECT id FROM home_recommendation WHERE id=?",id);db.update("UPDATE home_recommendation SET status='OFFLINE' WHERE id=?",id);}
 public Map<String,Object> page(String key){return db.one("SELECT v.id version_id,p.page_key,v.version_no,v.title,v.content,v.published_at FROM content_page p JOIN content_page_version v ON v.page_id=p.id AND v.version_no=p.version_no WHERE p.page_key=? AND p.tenant_id='000000' AND p.status='PUBLISHED'",key);}
 public List<Map<String,Object>> pages(){manage();return db.rows("SELECT p.id,p.page_key,p.title,p.version_no,p.status FROM content_page p WHERE tenant_id='000000' ORDER BY p.page_key");}
 @Transactional public Map<String,Object> page(Page b){manage();BusinessException.require(b.pageKey!=null&&b.pageKey.matches("[a-z_]{2,40}"),422,"页面key错误");Db.text(b.title,150);String content=Db.text(b.content,100000);db.rows("SELECT id FROM content_page WHERE tenant_id='000000' ORDER BY id FOR UPDATE");var old=db.rows("SELECT * FROM content_page WHERE page_key=? AND tenant_id='000000'",b.pageKey);long id=old.isEmpty()?db.id():Db.number(old.get(0).get("id")),version=old.isEmpty()?1:Db.number(old.get(0).get("versionNo"))+1;
  if(old.isEmpty())db.update("INSERT INTO content_page(id,page_key,title,content,version_no,updated_by) VALUES(?,?,?,?,?,?)",id,b.pageKey,b.title,content,version,actors.staff().id());else db.update("UPDATE content_page SET title=?,content=?,version_no=?,updated_by=? WHERE id=?",b.title,content,version,actors.staff().id(),id);
  db.update("INSERT INTO content_page_version(id,page_id,version_no,title,content) VALUES(?,?,?,?,?)",db.id(),id,version,b.title,content);db.audit(actors.staff().id(),"STAFF","PAGE_PUBLISH","PAGE",id,Map.of("version",version));return page(b.pageKey);}
 @Transactional public Map<String,Object> column(Column b){manage();db.one("SELECT id FROM content_category WHERE id=? AND tenant_id='000000' AND status='ENABLED' AND deleted_at IS NULL",b.categoryId);BusinessException.require(Set.of("ENABLED","DISABLED").contains(b.status),422,"栏目状态错误");long id=db.id();db.update("INSERT INTO activity_column(id,name,category_id,sort_order,status) VALUES(?,?,?,?,?)",id,Db.text(b.name,100),b.categoryId,b.sortOrder,b.status);return db.one("SELECT * FROM activity_column WHERE id=?",id);}
 public List<Map<String,Object>> audit(){actors.staff().require("yunji:audit:read");return db.rows("SELECT id,actor_id,actor_client,action,object_type,object_id,request_id,created_at FROM audit_event WHERE tenant_id='000000' ORDER BY created_at DESC,id DESC LIMIT 500");}
}
